import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{L as e,x as p,A as l,G as s,M as i,Z as o,B as r}from"./chunks/runtime-core.esm-bundler.BPWg86ya.js";const u="/assets/aiAgent.DUcfc9cR.jpg",k=JSON.parse('{"title":"AI Agent 全解析","description":"","frontmatter":{},"headers":[],"relativePath":"column/AIFuture/基础认知/AI Agent 全解析.md","filePath":"column/AIFuture/基础认知/AI Agent 全解析.md","lastUpdated":1791960421000}'),c={name:"column/AIFuture/基础认知/AI Agent 全解析.md"};function d(g,n,b,h,q,m){const a=e("ArticleMetadata");return l(),p("div",null,[n[0]||(n[0]=s("h1",{id:"ai-agent-全解析",tabindex:"-1"},[r("AI Agent 全解析 "),s("a",{class:"header-anchor",href:"#ai-agent-全解析","aria-label":'Permalink to "AI Agent 全解析"'},"​")],-1)),i(a),n[1]||(n[1]=o('<nav class="table-of-contents"><ul><li><a href="#一、agent-是什么-给-llm-装上-手脚">一、Agent 是什么：给 LLM 装上&quot;手脚&quot;</a></li><li><a href="#二、agent-的基本架构-五个核心部件">二、Agent 的基本架构：五个核心部件</a></li><li><a href="#三、agent-的运行流程-一个永不停歇的-loop">三、Agent 的运行流程：一个永不停歇的 Loop</a></li><li><a href="#四、react-agent-循环的经典范式">四、ReAct：Agent 循环的经典范式</a></li><li><a href="#五、planning-agent-如何拆解任务">五、Planning：Agent 如何拆解任务</a></li><li><a href="#六、tool-调用-agent-如何-动手">六、Tool 调用：Agent 如何&quot;动手&quot;</a></li><li><a href="#七、memory-agent-如何-记住">七、Memory：Agent 如何&quot;记住&quot;</a><ul><li><a href="#长期记忆为什么用向量数据库">长期记忆为什么用向量数据库？</a></li></ul></li><li><a href="#八、状态管理-把每一步-串-起来">八、状态管理：把每一步&quot;串&quot;起来</a></li><li><a href="#九、multi-agent-从-一个人-到-一个团队">九、Multi-Agent：从&quot;一个人&quot;到&quot;一个团队&quot;</a></li><li><a href="#总结-一张图看懂-ai-agent">总结：一张图看懂 AI Agent</a></li></ul></nav><p><img src="'+u+`" alt="" loading="lazy"></p><p><strong>AI Agent 全解析：从&quot;会说话&quot;到&quot;会干活&quot;</strong></p><p>很多人都有过这样的体验：ChatGPT 能流利地回答任何问题，但一旦让它&quot;帮我订一张下周三去上海的机票，顺便查一下那边三天的天气&quot;，它就只会输出一段&quot;建议你这么办&quot;的文字，而不是真正把票订了、把天气查了。</p><p>问题的根源很简单：<strong>大语言模型（LLM）只会&quot;说&quot;，不会&quot;做&quot;</strong>。它的本质是预测下一个 token——它能生成文字，却不能调用外部工具、不能记住上次说过的话、也不能自己拆解并执行一个多步骤任务。</p><p>而 AI Agent（智能体），正是为了解决这个问题而生。它给 LLM 装上了一套能&quot;思考、规划、动手、记忆、循环推进&quot;的完整框架，让 AI 从被动应答的&quot;聊天工具&quot;，进化成主动完成任务的&quot;数字员工&quot;。</p><p>本文按一条清晰的线索展开：先搞懂 Agent 是什么、由什么组成，再看它如何通过一个循环不断运转，最后深入到它的每个&quot;器官&quot;，并延伸到多智能体协作。</p><h2 id="一、agent-是什么-给-llm-装上-手脚" tabindex="-1">一、Agent 是什么：给 LLM 装上&quot;手脚&quot; <a class="header-anchor" href="#一、agent-是什么-给-llm-装上-手脚" aria-label="Permalink to &quot;一、Agent 是什么：给 LLM 装上&quot;手脚&quot;&quot;">​</a></h2><p>先给一个一句话定义：</p><blockquote><p><strong>AI Agent = LLM（大脑） + 规划（Planning） + 工具（Tool） + 记忆（Memory），在一个循环（Loop）里自主完成任务。</strong></p></blockquote><p>拆开来看，它对应人的几项能力：</p><table tabindex="0"><thead><tr><th>人的能力</th><th>Agent 的对应部分</th><th>作用</th></tr></thead><tbody><tr><td>大脑</td><td>LLM</td><td>理解目标、推理、做决策</td></tr><tr><td>思考怎么做</td><td>Planning</td><td>把大任务拆成小步骤</td></tr><tr><td>双手</td><td>Tool 调用</td><td>查资料、写代码、调 API</td></tr><tr><td>记忆</td><td>Memory</td><td>记住上下文和中间结果</td></tr><tr><td>节奏感</td><td>Loop + 状态管理</td><td>一步步推进、知道做到哪了</td></tr></tbody></table><p>举个例子。你丢给它一句：&quot;帮我研究一下&#39;低代码平台&#39;这个赛道，写一份 500 字的行业简报。&quot;</p><p>一个普通的 LLM 会直接凭空写一篇（还可能是编的）。而一个 Agent 会这样干：</p><ol><li>先规划：拆成&quot;搜索资料 → 阅读整理 → 提炼要点 → 写简报 → 自查&quot;几步；</li><li>再动手：调用搜索工具查资料、调用阅读工具读网页；</li><li>边做边记：把查到的要点存进记忆；</li><li>循环推进：每完成一步，检查结果，决定下一步；</li><li>最终交付一份基于真实资料的简报。</li></ol><p>看明白了吗？Agent 和 LLM 最大的区别，就在于<strong>多了一个&quot;闭环&quot;</strong>——它能自己规划、自己行动、自己检查、自己调整，直到把事情办成。</p><h2 id="二、agent-的基本架构-五个核心部件" tabindex="-1">二、Agent 的基本架构：五个核心部件 <a class="header-anchor" href="#二、agent-的基本架构-五个核心部件" aria-label="Permalink to &quot;二、Agent 的基本架构：五个核心部件&quot;">​</a></h2><p>无论哪个框架（LangChain、AutoGPT、自研），一个 Agent 的骨架基本一致：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>             ┌────────────────────────────────┐</span></span>
<span class="line"><span>             │         用户目标 (Goal)          │</span></span>
<span class="line"><span>             └────────────────────────────────┘</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>        ┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>        │               AI Agent                  │</span></span>
<span class="line"><span>        │                                          │</span></span>
<span class="line"><span>        │   ┌──────┐   ┌──────────┐   ┌────────┐  │</span></span>
<span class="line"><span>        │   │ LLM  │←→│ Planning │←→│ Memory │  │</span></span>
<span class="line"><span>        │   │(大脑) │   │ (规划)   │   │ (记忆) │  │</span></span>
<span class="line"><span>        │   └──────┘   └──────────┘   └────────┘  │</span></span>
<span class="line"><span>        │        ↕                ↕                │</span></span>
<span class="line"><span>        │   ┌──────────────────────────┐           │</span></span>
<span class="line"><span>        │   │        Tool 调用          │           │</span></span>
<span class="line"><span>        │   │  搜索/代码/API/数据库     │           │</span></span>
<span class="line"><span>        │   └──────────────────────────┘           │</span></span>
<span class="line"><span>        └─────────────────────────────────────────┘</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                        执行结果 (Result)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p>这五个部件各司其职：</p><ul><li><strong>LLM（大脑）</strong>：负责理解、推理、做决策，是 Agent 的核心；</li><li><strong>Planning（规划）</strong>：把大目标拆解成可执行的子任务；</li><li><strong>Tool（工具）</strong>：Agent 的&quot;手脚&quot;，用来查资料、跑代码、调接口；</li><li><strong>Memory（记忆）</strong>：存储上下文、中间结果和长期知识；</li><li><strong>Loop + State（循环与状态）</strong>：把以上部件串成一个持续推进的流程。</li></ul><p>后面几节，我们就沿着&quot;这个骨架是怎么转起来的&quot;这条线，一个个拆开讲。</p><h2 id="三、agent-的运行流程-一个永不停歇的-loop" tabindex="-1">三、Agent 的运行流程：一个永不停歇的 Loop <a class="header-anchor" href="#三、agent-的运行流程-一个永不停歇的-loop" aria-label="Permalink to &quot;三、Agent 的运行流程：一个永不停歇的 Loop&quot;">​</a></h2><p>Agent 干活的核心，是一个循环（Agent Loop）。它大致长这样：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         ┌──────────────────────────────┐</span></span>
<span class="line"><span>         │                              │</span></span>
<span class="line"><span>         ↓                              │</span></span>
<span class="line"><span>   观察当前状态 (Observation)           │</span></span>
<span class="line"><span>         │                              │</span></span>
<span class="line"><span>         ↓                              │</span></span>
<span class="line"><span>   思考下一步该做什么 (Thought)          │</span></span>
<span class="line"><span>         │                              │</span></span>
<span class="line"><span>         ↓                              │</span></span>
<span class="line"><span>   执行一个动作 (Action) ────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>这个循环为什么如此重要？因为<strong>现实任务往往不是一步到位的</strong>。你没法一次就&quot;订好机票&quot;——你得先查航班、再比价、再下单、再确认，中间每一步的结果都会影响下一步。</p><p>所以 Agent 不是&quot;一次输出答案&quot;，而是&quot;反复地：看 → 想 → 做 → 再看&quot;，直到达成目标。这个循环，就是 Agent 的&quot;心跳&quot;。</p><p>一个关键点是：<strong>循环需要有退出条件</strong>。要么任务完成，要么达到最大步数，要么发现自己卡死了需要向用户求助——否则 Agent 会陷入无限循环。这就是为什么后面要专门讲&quot;状态管理&quot;。</p><h2 id="四、react-agent-循环的经典范式" tabindex="-1">四、ReAct：Agent 循环的经典范式 <a class="header-anchor" href="#四、react-agent-循环的经典范式" aria-label="Permalink to &quot;四、ReAct：Agent 循环的经典范式&quot;">​</a></h2><p>把上面的循环落地到代码层面，最经典、最常用的范式就是 <strong>ReAct（Reasoning + Acting，推理 + 行动）</strong>。</p><p>ReAct 把每一步循环拆成三个动作：</p><table tabindex="0"><thead><tr><th>步骤</th><th>含义</th><th>例子</th></tr></thead><tbody><tr><td><strong>Thought（思考）</strong></td><td>模型推理&quot;现在该怎么办&quot;</td><td>&quot;用户想知道上海天气，我需要调用天气工具&quot;</td></tr><tr><td><strong>Action（行动）</strong></td><td>输出一个可执行的调用</td><td><code>get_weather(city=&quot;上海&quot;)</code></td></tr><tr><td><strong>Observation（观察）</strong></td><td>拿到工具返回的结果</td><td>&quot;上海，晴，25℃&quot;</td></tr></tbody></table><p>然后基于 Observation，模型继续 Thought → Action → Observation……直到回答用户。</p><p>用代码视角看，ReAct 就是让 LLM 交替输出&quot;思考&quot;和&quot;动作&quot;：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thought: 用户想查上海天气，我需要调用天气工具。</span></span>
<span class="line"><span>Action: get_weather(city=&quot;上海&quot;)</span></span>
<span class="line"><span>Observation: 上海，晴，25℃</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Thought: 拿到结果了，可以回答用户了。</span></span>
<span class="line"><span>Answer: 上海今天晴，气温 25℃。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>为什么 ReAct 这么重要？因为它把&quot;推理&quot;和&quot;行动&quot;绑在了一起：光思考不行动（纯 CoT）没法获取外部信息；光行动不思考（瞎调工具）会跑偏。ReAct 让两者交替进行，既聪明又能干。</p><h2 id="五、planning-agent-如何拆解任务" tabindex="-1">五、Planning：Agent 如何拆解任务 <a class="header-anchor" href="#五、planning-agent-如何拆解任务" aria-label="Permalink to &quot;五、Planning：Agent 如何拆解任务&quot;">​</a></h2><p>循环决定了&quot;怎么走&quot;，而 <strong>Planning（规划）决定了&quot;先做什么、后做什么&quot;</strong>。</p><p>面对一个复杂目标，Agent 不会（也不应该）上来就动手，而是先规划：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标：写一份&quot;低代码平台&quot;行业简报</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ├─ 1. 搜索&quot;低代码平台 市场规模 2026&quot;</span></span>
<span class="line"><span>   ├─ 2. 阅读并摘录 3-5 篇权威来源</span></span>
<span class="line"><span>   ├─ 3. 提炼核心观点</span></span>
<span class="line"><span>   ├─ 4. 生成 500 字简报</span></span>
<span class="line"><span>   └─ 5. 自查：数据是否有来源、是否跑题</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>规划能力主要靠两种手段：</p><ol><li><strong>任务分解（Task Decomposition）</strong>：把大目标递归拆成小步骤。类似思维链（CoT），但更偏&quot;行动&quot;，是&quot;先计划再执行&quot;。</li><li><strong>反思与修正（Self-Reflection）</strong>：执行过程中发现某一步错了（比如搜到的数据是旧的），就退回重做或调整计划。</li></ol><p>一句话总结：<strong>Planning 让 Agent 从&quot;想到哪做到哪&quot;，变成&quot;先谋后动&quot;</strong>。这正是 Agent 能处理复杂任务、而不是只能回答单个问题的关键。</p><h2 id="六、tool-调用-agent-如何-动手" tabindex="-1">六、Tool 调用：Agent 如何&quot;动手&quot; <a class="header-anchor" href="#六、tool-调用-agent-如何-动手" aria-label="Permalink to &quot;六、Tool 调用：Agent 如何&quot;动手&quot;&quot;">​</a></h2><p>规划再好，没有&quot;手脚&quot;也白搭。<strong>Tool 调用（工具调用）是 Agent 从&quot;说&quot;跨越到&quot;做&quot;的桥梁。</strong></p><p>技术上，它依赖 <strong>Function Calling（函数调用）</strong>。核心机制是：模型不直接输出最终文字，而是输出一个<strong>结构化的调用指令</strong>，交给系统去执行：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tool&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;get_weather&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;city&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;上海&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>系统收到这个 JSON，就调用对应的 <code>get_weather</code> 函数，拿到结果后<strong>再交还给模型</strong>，让模型继续推理。</p><p>整个过程是一次&quot;模型 ↔ 工具&quot;的接力：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户提问 → LLM 输出调用指令 → 系统执行工具 → 结果回传 → LLM 生成回答</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>常见的工具包括：搜索引擎、代码解释器、数据库查询、各种外部 API（天气、地图、邮件）。而像 MCP 这样的协议，正是为了让模型能&quot;即插即用&quot;地接更多工具。</p><p>注意一个细节：<strong>工具的结果要回到模型手里</strong>，模型才能决定下一步。所以 Tool 调用天然和 Loop 绑定在一起——调完工具、拿到结果、继续循环。</p><h2 id="七、memory-agent-如何-记住" tabindex="-1">七、Memory：Agent 如何&quot;记住&quot; <a class="header-anchor" href="#七、memory-agent-如何-记住" aria-label="Permalink to &quot;七、Memory：Agent 如何&quot;记住&quot;&quot;">​</a></h2><p>循环跑起来之后，马上会遇到一个现实问题：<strong>上下文会爆</strong>。</p><p>LLM 的上下文窗口是有限的，而 Agent 执行任务时会积累大量中间结果（搜索记录、工具输出、历史步骤）。如果全塞进上下文，很快就会超限、变慢、甚至丢失早期信息。</p><p>所以 Agent 需要 <strong>Memory（记忆）</strong>，通常分三层：</p><table tabindex="0"><thead><tr><th>记忆类型</th><th>存什么</th><th>放哪里</th><th>作用</th></tr></thead><tbody><tr><td><strong>短期记忆</strong></td><td>当前对话/任务上下文</td><td>上下文窗口</td><td>维持连贯性</td></tr><tr><td><strong>工作记忆</strong></td><td>当前任务的中间结果、变量</td><td>状态对象（内存）</td><td>跨步骤传递信息</td></tr><tr><td><strong>长期记忆</strong></td><td>历史经验、用户偏好、知识</td><td>向量库/数据库</td><td>跨会话复用</td></tr></tbody></table><p>通俗地说：</p><ul><li>短期记忆是&quot;我现在正在想的事&quot;；</li><li>工作记忆是&quot;我干活时写在便签上的笔记&quot;；</li><li>长期记忆是&quot;我记在笔记本里、下次还能翻出来用的东西&quot;。</li></ul><h3 id="长期记忆为什么用向量数据库" tabindex="-1">长期记忆为什么用向量数据库？ <a class="header-anchor" href="#长期记忆为什么用向量数据库" aria-label="Permalink to &quot;长期记忆为什么用向量数据库？&quot;">​</a></h3><p>这里&quot;长期记忆&quot;为什么专门放在<strong>向量库</strong>里，值得单独展开——它背后是 Agent 记忆最关键的底层设施。</p><p>长期记忆的核心难点在于：Agent 要&quot;回忆起&quot;和当前问题相关的内容，靠的不是一模一样的关键词，而是&quot;意思相近&quot;。</p><p>举个例子：用户先说过&quot;我想去东京玩&quot;，过几天又问&quot;上次说的日本行程定了吗？&quot;——两句话措辞完全不同，Agent 却要能联想到&quot;东京&quot;和&quot;日本行程&quot;是同一件事。</p><p>这正是向量数据库擅长的事，思路分两步：</p><ol><li><strong>写入时</strong>：用 Embedding 模型把每段记忆变成一串数字（向量）。语义相近的文字，转成的向量在空间里也离得近；</li><li><strong>读取时</strong>：把当前问题也转成向量，去数据库里找&quot;距离最近&quot;的那几条记忆，召回最相关的内容。</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文字 → Embedding → 向量（一串数字） → 存入向量库</span></span>
<span class="line"><span>查询 → Embedding → 查询向量 → 相似度搜索 → 召回最相关的记忆</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>那向量数据库里到底存的是什么？答案是：<strong>向量 + 它对应的原文（和可选元数据），两者一起存</strong>。</p><ul><li><strong>向量</strong>：一串数字，是 Embedding 算出来的&quot;语义指纹&quot;，只负责算相似度；</li><li><strong>原文</strong>：这段向量对应的原始文字，召回后真正要拿出来用的内容；</li><li><strong>元数据</strong>：可选的附加信息（ID、用户、时间等），用于过滤和追溯。</li></ul><p>一条记录大致长这样：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>id: &quot;mem-001&quot;</span></span>
<span class="line"><span>vector: [0.02, -0.11, 0.87, ..., 0.45]      ← 用于相似度计算</span></span>
<span class="line"><span>text:   &quot;用户喜欢去东京旅游，预算 8000 元&quot;    ← 召回后真正使用的原文</span></span>
<span class="line"><span>meta:   { user: &quot;u_123&quot;, time: &quot;2026-10-01&quot; }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>关键就一句：<strong>向量是&quot;找&quot;用的钥匙，原文是&quot;用&quot;的内容</strong>。光存一堆数字没有意义，召回之后你得知道这段数字对应的是哪段文字。</p><p>和传统数据库对比一下就更清楚了：</p><table tabindex="0"><thead><tr><th>传统数据库</th><th>向量数据库</th></tr></thead><tbody><tr><td>精确匹配：<code>WHERE 姓名 = &#39;张三&#39;</code></td><td>语义匹配：找&quot;意思最接近&quot;的内容</td></tr><tr><td>存结构化数据（表、字段）</td><td>存向量（一串数字）</td></tr><tr><td>查&quot;相等 / 范围&quot;</td><td>查&quot;相似度&quot;</td></tr></tbody></table><p>常见的向量数据库有 Pinecone、Milvus、Weaviate、Qdrant、Chroma，以及带 pgvector 扩展的 PostgreSQL。</p><blockquote><p>一句话：向量数据库解决的是&quot;语义记忆&quot;的存取问题——它让 Agent 能&quot;想起意思相近、而非字面相同的过去&quot;。</p></blockquote><p>Memory 的意义在于：<strong>让 Agent 不必把一切都记在脑子里（上下文），而是该存就存、该取就取</strong>，既节省上下文，又能跨步骤、跨会话保持连续性。</p><h2 id="八、状态管理-把每一步-串-起来" tabindex="-1">八、状态管理：把每一步&quot;串&quot;起来 <a class="header-anchor" href="#八、状态管理-把每一步-串-起来" aria-label="Permalink to &quot;八、状态管理：把每一步&quot;串&quot;起来&quot;">​</a></h2><p>前面讲了循环、规划、工具、记忆，它们之间靠什么协同？答案是 <strong>状态（State）</strong>。</p><p>可以把状态理解成 Agent 的&quot;工作台面板&quot;——它记录着：</p><ul><li>当前做到哪一步了；</li><li>已经拿到了哪些中间结果；</li><li>下一步计划是什么；</li><li>目标有没有变化。</li></ul><p>为什么状态管理如此关键？回到第三节那个循环：<strong>循环要能正确推进，靠的就是状态在每一步之间的传递和更新</strong>。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初始状态：目标=写简报，步骤=[]，结果={}</span></span>
<span class="line"><span>   ↓ (执行第1步)</span></span>
<span class="line"><span>状态更新：步骤=[搜索]，结果={关键词列表}</span></span>
<span class="line"><span>   ↓ (执行第2步)</span></span>
<span class="line"><span>状态更新：步骤=[搜索,阅读]，结果={关键词列表, 摘要}</span></span>
<span class="line"><span>   ↓ ...</span></span>
<span class="line"><span>最终状态：步骤=[...全部完成]，结果={简报草稿}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>状态管理带来三个实实在在的好处：</p><ol><li><strong>不失控</strong>：明确&quot;下一步做什么&quot;，避免循环乱转；</li><li><strong>可恢复</strong>：中途失败可以从上一个状态继续，而不是从头再来；</li><li><strong>可观测</strong>：任何时候都能看清&quot;做到哪了&quot;，方便调试和给用户解释。</li></ol><p>可以说，<strong>状态是 Agent 的&quot;主线&quot;，把循环、规划、工具、记忆串成了一个整体</strong>。理解了状态，才算真正理解了 Agent 的运行机制。</p><h2 id="九、multi-agent-从-一个人-到-一个团队" tabindex="-1">九、Multi-Agent：从&quot;一个人&quot;到&quot;一个团队&quot; <a class="header-anchor" href="#九、multi-agent-从-一个人-到-一个团队" aria-label="Permalink to &quot;九、Multi-Agent：从&quot;一个人&quot;到&quot;一个团队&quot;&quot;">​</a></h2><p>单 Agent 有天花板：一个模型既要规划、又要搜索、又要写代码、又要自查，角色太多就容易顾此失彼。</p><p>于是自然演进出了 <strong>Multi-Agent（多智能体）</strong>：把任务分给多个各司其职的 Agent，让它们协作完成。</p><p>常见形态有两种：</p><ol><li><strong>编排者模式（Orchestrator）</strong>：一个&quot;主管 Agent&quot;负责拆解任务、派活、汇总结果，下面一群&quot;工人 Agent&quot;各干各的。</li></ol><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>            主管 Agent (编排者)</span></span>
<span class="line"><span>          /     |      \\</span></span>
<span class="line"><span>         ↓      ↓       ↓</span></span>
<span class="line"><span>     研究员    写手    审校员</span></span>
<span class="line"><span>    (搜索资料) (写作)  (检查纠错)</span></span>
<span class="line"><span>         \\      |      /</span></span>
<span class="line"><span>          ↓     ↓     ↓</span></span>
<span class="line"><span>            汇总成最终成果</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><ol start="2"><li><strong>对等协作模式（Peer-to-Peer）</strong>：多个 Agent 平等对话、互相调用，像一场会议，你来我往地推进任务。</li></ol><p>Multi-Agent 的价值很直观：</p><ul><li><strong>分工更专业</strong>：研究员专心搜索、写手专心写作、审校专心挑错，质量更高；</li><li><strong>能力可扩展</strong>：需要新技能就加一个新 Agent，而不是把一个大模型越做越臃肿；</li><li><strong>可相互校验</strong>：多个 Agent 可以交叉检查，减少幻觉。</li></ul><p>当然，它也带来新的挑战——比如 Agent 之间怎么通信、怎么共享记忆、怎么避免&quot;互相踢皮球&quot;。这些本质上又回到了前文的主题：<strong>通信靠状态，共享靠记忆，协调靠一个更高层的 Loop</strong>。</p><p>所以 Multi-Agent 不是另起炉灶，而是把前面所有概念&quot;放大成一个团队&quot;来用。</p><h2 id="总结-一张图看懂-ai-agent" tabindex="-1">总结：一张图看懂 AI Agent <a class="header-anchor" href="#总结-一张图看懂-ai-agent" aria-label="Permalink to &quot;总结：一张图看懂 AI Agent&quot;">​</a></h2><p>回到最开始那句话：<strong>AI Agent 就是给 LLM 装上一套&quot;能思考、能动手、能记忆、能规划、能循环推进&quot;的框架。</strong></p><p>把整条线索串起来：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  为什么需要 Agent？      LLM 只会说，不会做</span></span>
<span class="line"><span>           ↓</span></span>
<span class="line"><span>  Agent 是什么？           LLM + 规划 + 工具 + 记忆 + 循环</span></span>
<span class="line"><span>           ↓</span></span>
<span class="line"><span>  怎么运转？               Loop 循环：观察 → 思考 → 行动 → 再观察</span></span>
<span class="line"><span>           ↓</span></span>
<span class="line"><span>  循环的经典范式？         ReAct：Thought / Action / Observation</span></span>
<span class="line"><span>           ↓</span></span>
<span class="line"><span>  各部件怎么配合？         Planning 拆任务 → Tool 执行 → Memory 记结果</span></span>
<span class="line"><span>           ↓</span></span>
<span class="line"><span>  怎么不失控？             状态管理把每一步串起来</span></span>
<span class="line"><span>           ↓</span></span>
<span class="line"><span>  怎么更强？                Multi-Agent 多智能体协作</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>理解了这条线，你就抓住了 AI Agent 的全部骨架。至于框架选型、工程细节，那都是在这套骨架上的具体实现——万变不离其宗。</p>`,101))])}const y=t(c,[["render",d]]);export{k as __pageData,y as default};
